// Drives a gpt-live-1 session with TTS audio and answers delegations, to learn the protocol.
const KEY = process.env.OPENAI_API_KEY;
const say = async text => {
  const r = await fetch("https://api.openai.com/v1/audio/speech", { method: "POST", headers: { Authorization: `Bearer ${KEY}`, "Content-Type": "application/json" },
    body: JSON.stringify({ model: "gpt-4o-mini-tts", voice: "alloy", input: text, response_format: "pcm" }) });
  if (!r.ok) throw new Error(`tts ${r.status} ${await r.text()}`);
  return Buffer.from(await r.arrayBuffer());
};
const t0 = Date.now(); const log = (...a) => console.log(((Date.now() - t0) / 1000).toFixed(2).padStart(6), ...a);
const utterances = process.argv.slice(2).length ? process.argv.slice(2) : ["Hey, how much did I spend at Netto this month?"];
const clips = await Promise.all(utterances.map(say));
const ws = new WebSocket("wss://api.openai.com/v1/live/sessions", { headers: { Authorization: `Bearer ${KEY}` } });
const send = e => ws.send(JSON.stringify(e));
let out = "", inp = "";
ws.onopen = () => { log("open");
  send({ type: "session.start", session: { model: "gpt-live-1", instructions: "You are Moneo, a casual friendly finance assistant. Never state money amounts yourself. Generate <|SpawnThinking|> whenever the user asks about their money, spending, balances or wants to add something.", audio: { format: { type: "audio/pcm", rate: 24000 }, output: { voice: "marin" } }, delegation: { type: "client" } } });
};
const stream = async pcm => { const chunk = 4800; // 100ms at 24kHz 16-bit
  for (let i = 0; i < pcm.length; i += chunk) { send({ type: "session.input_audio.append", audio: pcm.subarray(i, i + chunk).toString("base64") }); await new Promise(r => setTimeout(r, 100)); } };
const silence = ms => Buffer.alloc(48 * ms);
ws.onmessage = async m => { const e = JSON.parse(m.data);
  if (e.type === "session.output_audio.delta") return;
  if (e.type === "session.input_transcript.delta") { inp += e.delta; return; }
  if (e.type === "session.output_transcript.delta") { out += e.delta; return; }
  if (inp) { log("USER:", inp); inp = ""; } if (out) { log("MONEO:", out); out = ""; }
  log(e.type, JSON.stringify(e).slice(0, 300));
  if (e.type === "session.started") { for (const c of clips) { await stream(c); await stream(silence(1500)); } await stream(silence(14000)); send({ type: "session.close" }); }
